((select id from scenarios where slug = 'brute-force-lateral-movement'), 'alert-scanner', 'ticket'::asset_type, '{"kind":"alert","id":"alert-scanner","title":"Inbound scanning denied at perimeter","severity":"info","source":"Perimeter Firewall","first_seen":"2025-04-22T00:55:41.000Z","description":"Routine internet background scanning from 198.51.100.140. Every attempt denied by the default-deny inbound policy. No action required.","is_decoy":true,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":[],"linked_log_ids":["log-fw-n001","log-fw-n002"]}'::jsonb, true, 'triage'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'alert-exposed-rdp', 'ticket'::asset_type, '{"kind":"alert","id":"alert-exposed-rdp","title":"RDP reachable from the public internet","severity":"medium","source":"Configuration Monitoring","first_seen":"2025-04-22T01:12:03.000Z","description":"The perimeter firewall policy Remote-Access-Legacy permits inbound 3389 from any source address to the jump host. The rule has been in place since March 2021.","host":"JMP-RDP-01","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":["doc-firewall-rule"],"linked_log_ids":["log-fw-rdp-allow"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'alert-bruteforce', 'ticket'::asset_type, '{"kind":"alert","id":"alert-bruteforce","title":"Burst of failed remote logons followed by a success","severity":"high","source":"Identity Monitoring","first_seen":"2025-04-22T01:48:30.000Z","description":"43 failed RemoteInteractive logons against JMP-RDP-01 from a single internet address over 36 minutes, spread across nine accounts, then one success. The successful account is svc_helpdesk.","host":"JMP-RDP-01","user":"svc_helpdesk","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":["doc-auth-report"],"linked_log_ids":["log-auth-spike","log-auth-success"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'alert-lateral', 'ticket'::asset_type, '{"kind":"alert","id":"alert-lateral","title":"Remote process creation on a file server","severity":"critical","source":"Northwind EDR","first_seen":"2025-04-22T01:52:41.000Z","description":"wmic.exe on JMP-RDP-01 created a process on FS-ACAD-02 using the svc_helpdesk account. An unsigned service binary appeared on the file server thirty seconds later.","host":"FS-ACAD-02","user":"svc_helpdesk","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":120,"linked_document_ids":[],"linked_log_ids":["log-edr-wmic","log-edr-psexec","log-auth-smb"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'alert-staging', 'ticket'::asset_type, '{"kind":"alert","id":"alert-staging","title":"Large archive written to a hidden share","severity":"critical","source":"File Activity Monitoring","first_seen":"2025-04-22T02:05:47.000Z","description":"A 2.1 GB zip archive of the AcademicRecords share was written to \\\\FS-ACAD-02\\temp$ by svc_helpdesk. Nothing schedules this.","host":"FS-ACAD-02","user":"svc_helpdesk","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":260,"linked_document_ids":["doc-share-listing"],"linked_log_ids":["log-fs-archive","log-edr-7z"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'alert-exfil', 'ticket'::asset_type, '{"kind":"alert","id":"alert-exfil","title":"Sustained outbound transfer from a file server","severity":"critical","source":"Network Detection","first_seen":"2025-04-22T02:31:04.000Z","description":"FS-ACAD-02 uploaded 2.1 GB over HTTPS to 198.51.100.23 across 27 minutes - the same address that brute-forced the jump host. This matches the size of the staged archive exactly.","host":"FS-ACAD-02","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":400,"linked_document_ids":[],"linked_log_ids":["log-fw-exfil-001","log-fw-exfil-total"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'log-auth-n001', 'auth_log'::asset_type, '{"kind":"log","id":"log-auth-n001","ts":"2025-04-22T00:30:00.000Z","source":"auth","message":"EventID=4624 Logon Type=5 (Service) Account=NORTHWIND\\svc_backup Workstation=FS-ACAD-02 Status=Success","host":"FS-ACAD-02","user":"svc_backup","action":"logon_success","fields":{"event_id":4624,"logon_type":5,"note":"Nightly backup job. Runs at 00:30 every night."},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'log-fs-n001', 'file_share_log'::asset_type, '{"kind":"log","id":"log-fs-n001","ts":"2025-04-22T00:31:12.000Z","source":"fileshare","message":"READ host=FS-ACAD-02 user=NORTHWIND\\svc_backup share=\\\\FS-ACAD-02\\AcademicRecords operation=backup files=14822","host":"FS-ACAD-02","user":"svc_backup","action":"backup","fields":{"share":"AcademicRecords","note":"Expected: this is what a backup looks like."},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
