((select id from scenarios where slug = 'brute-force-lateral-movement'), 'log-edr-n001', 'edr_alert'::asset_type, '{"kind":"log","id":"log-edr-n001","ts":"2025-04-22T01:05:55.000Z","source":"edr","message":"PROCESS host=FS-ACAD-02 user=NT AUTHORITY\\SYSTEM parent=services.exe image=MsMpEng.exe args=\"scheduled scan\"","host":"FS-ACAD-02","action":"process_create","severity":"info","fields":{"note":"Scheduled antivirus scan."},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'log-fw-rdp-allow', 'firewall_log'::asset_type, '{"kind":"log","id":"log-fw-rdp-allow","ts":"2025-04-22T01:12:03.000Z","source":"firewall","message":"ALLOW proto=TCP src=198.51.100.23 dst=203.0.113.5 dport=3389 policy=Remote-Access-Legacy nat_to=10.20.1.60","host":"JMP-RDP-01","src_ip":"198.51.100.23","dst_ip":"203.0.113.5","action":"allow","severity":"medium","fields":{"policy":"Remote-Access-Legacy","dport":3389,"policy_created":"2021-03-08","policy_source_restriction":"any","note":"RDP published to the whole internet. Created as a temporary measure in 2021."},"is_decoy":false,"reveal_phase":"triage"}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'brute-force-lateral-movement'), 'log-auth-fail-001', 'auth_log'::asset_type, '{"kind":"log","id":"log-auth-fail-001","ts":"2025-04-22T01:12:09.000Z","source":"auth","message":"EventID=4625 Logon Type=10 (RemoteInteractive) Account=NORTHWIND\\a.lim Workstation=JMP-RDP-01 Source=198.51.100.23 Status=Failure Reason=Unknown user name or bad password","host":"JMP-RDP-01","user":"a.lim","src_ip":"198.51.100.23","action":"logon_failure","severity":"medium","fields":{"event_id":4625,"logon_type":10,"failure_reason":"0xC000006A"},"is_decoy":false,"reveal_phase":"investigation"}'::jsonb, false, 'investigation'::phase_key),
