  learning_objectives = excluded.learning_objectives,
  organization_name = excluded.organization_name,
  root_cause = excluded.root_cause,
  model_recommendations = excluded.model_recommendations,
  continues_from = excluded.continues_from,
  is_published = excluded.is_published;

delete from scenario_phases where scenario_id = (select id from scenarios where slug = 'ransomware-outbreak');

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'ransomware-outbreak'),
  'triage'::phase_key, 0,
  'Triage', 'Triage under active impact is a different job. You are not deciding
whether this is real - it is - you are deciding how much of the
institution is still savable and in what order.

The most useful number on your screen is the gap between hosts: roughly
two minutes. That is your budget.

Do not spend this phase understanding how it started. That matters
enormously and it matters second.
', array['Establish the scope of active encryption.', 'Assess severity and declare a major incident.', 'Escalate to the people who can authorise estate-wide action.']::text[],
  '{"decisions":[{"key":"alert_severity","prompt":"What severity do you assign?","help_md":"Five systems including a departmental file server, actively\nencrypting, with shadow copies already deleted.\n","type":"select","options":[{"value":"critical","label":"Critical","description":"Active, spreading destruction of data across multiple systems including shared infrastructure."},{"value":"high","label":"High","description":"Serious compromise of several endpoints."},{"value":"medium","label":"Medium","description":"Suspicious file activity requiring investigation."},{"value":"low","label":"Low","description":"Isolated endpoint issue."}],"expected":"critical","points":10,"rationale_md":"Critical, without hesitation, and this is the scenario that earns the\nword. Compare it with the phishing incident, where calling a single\nworkstation critical would have been an overreaction.\n\nHere: multiple systems, shared infrastructure, active destruction,\nlocal recovery already removed, and a spread rate of about one host\nevery two minutes. The severity scale exists so that this looks\ndifferent from that, and if everything is critical then nothing is.\n","require_rationale":false},{"key":"immediate_priority","prompt":"What is your first priority in the next five minutes?","help_md":"You cannot do everything at once and the spread is ongoing. Choose\nwhat you do first.\n","type":"select","options":[{"value":"stop_the_spread","label":"Stop the spread - isolate affected hosts and cut shared drive access","description":"Limit how many more systems are reached."},{"value":"identify_patient_zero","label":"Identify patient zero and the entry vector","description":"Understand the attack before acting on it."},{"value":"check_backups","label":"Verify the backups are intact","description":"Establish whether recovery is possible."},{"value":"contact_attacker","label":"Make contact using the address in the ransom note","description":"Open a channel to understand the demand."}],"expected":"stop_the_spread","points":15,"rationale_md":"**Stop the spread.** Every other scenario in this library rewards\nunderstanding before acting. This one inverts it, because the damage\nis accruing while you think and each host is roughly two minutes of\ndelay away from being encrypted.\n\nVerifying backups is essential and it is not more urgent than\npreventing more systems needing to be restored from them. Identifying\npatient zero is the whole second half of this exercise and none of it\nchanges what you do in the next five minutes.\n\nContacting the attacker is never the SOC''s call. It is a decision for\nleadership with legal advice, and making contact yourself forfeits\noptions the institution may need.\n","require_rationale":true}],"actions":[{"key":"declare-major-incident","event_type":"ESCALATE","label":"Declare a major incident and escalate to leadership","target":"Incident Management / Senior Leadership Team","description":"Invoke the major incident process. This needs decisions above the SOC, immediately.","is_correct":true,"points":10,"feedback_md":"Correct, and early. A ransomware outbreak requires decisions - about\ndisconnecting services, about communications, about whether to pay -\nthat no analyst should make alone or be left holding at 08:00.\n","requires_confirmation":false},{"key":"wait-and-observe","event_type":"ESCALATE","label":"Continue monitoring before escalating","target":"SOC queue","description":"Gather more information before waking senior staff.","is_correct":false,"points":15,"feedback_md":"You have spent your two-minute budget. Another host is encrypting.\n\nThe instinct to have complete information before escalating is a good\none in almost every other situation and actively harmful here.\nEscalate with what you have, and update as you learn.\n","requires_confirmation":true}],"hints":[{"key":"triage-hint-clock","text_md":"Look at the first-seen timestamps across the five hosts. Work out the\ninterval between them. That number tells you how much time analysis\ncosts you.\n","cost":3},{"key":"triage-hint-vss","text_md":"Two things happened in the minute *before* encryption began. Both are\nin the queue. They are the last warning any environment gets.\n","cost":3}]}'::jsonb, '{"required_decision_keys":["alert_severity","immediate_priority"],"required_action_keys":["declare-major-incident"],"required_ioc_values":[],"min_queries":1,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'ransomware-outbreak'),
  'investigation'::phase_key, 1,
  'Investigation', 'Now work out how this started. Useful searches:

- `host:WKS-HR-014` for the first system affected.
- `before:07:41` to see what preceded the encryption.
- `source:dns` and `source:proxy` for what the host talked to.

Work backwards from 07:41 and keep going past the point where it looks
like you have the answer. The interesting part of this incident is
earlier than the ransomware.

Read the prior-incident ticket in your documents. Read what it says was
done, and then read what it says was not.
', array['Identify the pre-encryption behaviour and what it was for.', 'Explain how the file server was encrypted without the malware moving host.', 'Trace the payload back to the 11 March incident.', 'Establish why a blocked domain still resolved.']::text[],
  '{"decisions":[{"key":"attack_techniques","prompt":"Which MITRE ATT&CK techniques does the evidence support?","type":"multi_select","options":[{"value":"T1486","label":"T1486 - Data Encrypted for Impact","description":"Encrypting data to disrupt access to it."},{"value":"T1490","label":"T1490 - Inhibit System Recovery","description":"Deleting shadow copies and backups to prevent restoration."},{"value":"T1489","label":"T1489 - Service Stop","description":"Stopping services so their locked files can be encrypted."},{"value":"T1566.001","label":"T1566.001 - Phishing: Spearphishing Attachment","description":"The original access, seven days earlier."},{"value":"T1110","label":"T1110 - Brute Force","description":"Repeated authentication attempts to guess credentials."},{"value":"T1190","label":"T1190 - Exploit Public-Facing Application","description":"Exploitation of an internet-facing service."},{"value":"T1021.002","label":"T1021.002 - Remote Services: SMB/Windows Admin Shares","description":"Lateral movement over SMB or admin shares."}],"expected":["T1486","T1490","T1489","T1566.001"],"points":20,"rationale_md":"Four techniques, and the fourth is the point of this scenario.\n\nT1486, T1490 and T1489 are the ransomware itself: encrypt, remove\nrecovery, stop the services holding files open. Including T1566.001\nsays something important - **the initial access was not today**. It\nwas the phishing attachment on 11 March, and this incident is its\ncontinuation.\n\nT1021.002 is the tempting wrong answer. The file server was\nencrypted, so it feels like lateral movement. But there was no SMB\nsession from an attacker tool and no remote execution: the malware\nwalked a mapped drive letter that was already mounted in the user''s\nsession. That distinction changes the remediation from \"segment the\nnetwork\" to \"restrict who can write to the share\".\n","require_rationale":false},{"key":"spread_mechanism","prompt":"How was FS-SHARED-01 encrypted?","type":"select","options":[{"value":"mapped_drive_from_workstation","label":"Over a mapped drive already mounted on WKS-HR-014","description":"The malware wrote through a drive letter in the user''s session."},{"value":"lateral_movement_smb","label":"The malware moved to the file server and ran there","description":"A remote execution technique placed the payload on the server."},{"value":"separate_infection","label":"The file server was infected independently","description":"It received its own copy of the payload."},{"value":"backup_agent_propagation","label":"The backup agent propagated the encrypted files","description":"Replication carried the damage across."}],"expected":"mapped_drive_from_workstation","points":15,"rationale_md":"A mapped drive. The file share log records the write operation with\n`source_host=WKS-HR-014` - the malware never ran on the server at\nall. It wrote 41,882 files through a drive letter that was mounted in\np.raman''s session because she uses it every day.\n\nThis matters because the two explanations lead to different fixes.\n\"Lateral movement\" suggests network segmentation and credential\nhardening. Mapped-drive encryption is not stopped by either: the\ntraffic is a legitimate user writing to a share they are permitted to\nwrite to. What stops it is restricting *what* that permission covers,\nso one HR workstation cannot rewrite every department''s folder.\n","require_rationale":true},{"key":"initial_access","prompt":"When and how did the attacker first gain access?","help_md":"Search before:07:41 on WKS-HR-014, and read the prior incident ticket.","type":"select","options":[{"value":"march_11_phishing_never_eradicated","label":"11 March, via a phishing attachment - and the implant was never removed","description":"The persistence from the earlier incident survived and launched again."},{"value":"today_via_email","label":"This morning, via a new phishing email","description":"A fresh delivery preceded the encryption."},{"value":"rdp_brute_force","label":"Through brute-forced remote access","description":"An attacker authenticated from outside."},{"value":"compromised_update","label":"A compromised software update","description":"A trusted update channel delivered the payload."}],"expected":"march_11_phishing_never_eradicated","points":20,"rationale_md":"Seven days ago, and the implant never left.\n\nThe evidence chain is unambiguous: at 07:37:55 p.raman logs in. At\n07:38:02 `onedrivesync.exe` starts from the Run key - the same file\nhash as the 11 March incident. At 07:38:09 it resolves\n`update-cdn.paylo4d.example`, the same C2 domain. At 07:39:21 it\ndownloads 1.8 MB. At 07:40:44 services stop, at 07:40:58 shadow\ncopies are deleted, at 07:41:12 encryption starts.\n\nThe whole outbreak took three minutes and seventeen seconds from a\nuser logging in.\n\nThe ticket tells you why. The domain was blocked at the proxy. The\nhost was not isolated, because the user needed her laptop during\npayroll week. It was not reimaged. The Run key was not removed. Her\ncredentials were not reset. And nobody swept the estate for the same\nindicators.\n\nEvery one of those was a defensible small decision under time\npressure. Together they are this Tuesday.\n","require_rationale":true},{"key":"proxy_block_failure","prompt":"The C2 domain was blocked on 11 March. Why did it still work?","type":"select","options":[{"value":"blocked_at_proxy_only","label":"It was blocked only at the web proxy, not at DNS or the firewall","description":"The implant reached it by a path the block did not cover."},{"value":"attacker_changed_domain","label":"The attacker registered a new domain","description":"The block was correct but no longer relevant."},{"value":"block_expired","label":"The block had a time limit that expired","description":"The rule was temporary."},{"value":"dns_cache_poisoning","label":"DNS cache poisoning circumvented the block","description":"Resolution was manipulated."}],"expected":"blocked_at_proxy_only","points":15,"rationale_md":"One layer, not all of them. The DNS log shows the domain resolving\nnormally at 07:38:09 and the firewall permitting the outbound\nconnection. The proxy block was real and the traffic simply did not\ngo through the proxy.\n\nThis is one of the most common gaps in practice. A block gets applied\nwhere it is easiest to apply, the ticket is closed, and nobody checks\nit from the affected host. Verifying a block **from the place it is\nsupposed to protect** takes two minutes and would have caught this.\n","require_rationale":false}],"actions":[],"hints":[{"key":"inv-hint-backwards","text_md":"Set your search to `before:07:41` on WKS-HR-014 and read forwards\nfrom 07:37. The three minutes before encryption contain the whole\nstory.\n","cost":5},{"key":"inv-hint-hash","text_md":"Compare the SHA-256 of the process that started the encryption with\nthe one in the 11 March incident ticket. They are the same file.\n","cost":5},{"key":"inv-hint-mapped","text_md":"Look at the `source_host` field on the file server''s write event.\nIt tells you which machine was doing the writing.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["attack_techniques","spread_mechanism","initial_access","proxy_block_failure"],"required_action_keys":[],"required_ioc_values":["onedrivesync.exe","update-cdn.paylo4d.example","HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run\\OneDriveSync"],"min_queries":4,"min_notes":1,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'ransomware-outbreak'),
  'containment'::phase_key, 2,
  'Containment', 'Containment here is broader than anything else in this library, and the
proportionality judgement runs the opposite way to the web application
scenario.

There, you knew exactly which two endpoints were vulnerable and taking
the whole portal down was disproportionate. Here you do not know which
hosts are compromised but not yet encrypting, and the cost of being wrong
is measured in departments.
', array['Isolate every affected host, not only the first.', 'Cut shared drive access to stop server-side encryption.', 'Protect the backup infrastructure above all else.', 'Close the C2 channel at every layer this time.']::text[],
  '{"decisions":[{"key":"containment_scope","prompt":"What containment do you authorise?","type":"select","options":[{"value":"isolate_all_affected_plus_shares_and_backup","label":"Isolate all five hosts, disable shared drive access estate-wide, and network-isolate the backup server","description":"Stop the spread and protect the only route to recovery."},{"value":"isolate_affected_only","label":"Isolate the five affected hosts","description":"Contain the systems known to be encrypting."},{"value":"isolate_patient_zero","label":"Isolate WKS-HR-014","description":"Contain the origin of the outbreak."},{"value":"shut_down_everything","label":"Power off every system on the campus network","description":"Total containment by disconnection."}],"expected":"isolate_all_affected_plus_shares_and_backup","points":15,"rationale_md":"All three elements, and the backup server is the one that decides\nwhether this institution recovers.\n\nIsolating the five known hosts is necessary and insufficient - you do\nnot know which others hold the same implant, and shared drives are\nthe spread mechanism. Disabling share access is disruptive and\nproportionate when 42,000 files have already gone that way.\n\nPowering everything off is worth taking seriously rather than\ndismissing: it is occasionally the right call, and in some outbreaks\nit is the only one. Here it is not, because it also loses the\nvolatile evidence needed to confirm eradication, and you have a\ntargeted option that addresses the actual spread mechanism.\n\nNote how the backup server is protected: by isolating it, not by\nusing it. Ransomware operators target backups deliberately, and this\none already tried locally with `vssadmin`.\n","require_rationale":true}],"actions":[{"key":"isolate-affected-hosts","event_type":"CONTAIN_HOST","label":"Network-isolate all five affected hosts","target":"WKS-HR-014, WKS-HR-015, WKS-FIN-003, WKS-ADM-021, FS-SHARED-01","description":"Cut all five from the network via the EDR console, leaving them powered on.","is_correct":true,"points":15,"feedback_md":"Correct, and powered on. The temptation to pull power during\nencryption is strong and usually wrong: memory may hold the\nencryption key, and it certainly holds evidence that a hard shutdown\ndestroys.\n","requires_confirmation":false},{"key":"isolate-backup-server","event_type":"CONTAIN_HOST","label":"Network-isolate BKP-SRV-01","target":"BKP-SRV-01","description":"Cut the backup server off from the production network to protect the only clean copy.","is_correct":true,"points":15,"feedback_md":"Correct, and the single most valuable action in this incident.\nRansomware operators go for backups deliberately. An intact backup is\nthe difference between a difficult week and a catastrophe.\n","requires_confirmation":false},{"key":"disable-share-access","event_type":"BLOCK_INDICATOR","label":"Disable write access to all departmental shares","target":"\\\\FS-SHARED-01\\Departments and all mapped shares","description":"Revoke write permissions estate-wide until affected hosts are identified.","is_correct":true,"points":15,"feedback_md":"Correct. This is what actually stops the spread mechanism - the\nmalware reached the file server through a drive letter, not through\nthe network in a way isolation alone would have caught.\n","requires_confirmation":false},{"key":"block-c2-all-layers","event_type":"BLOCK_INDICATOR","label":"Block the C2 domain and address at DNS, proxy and firewall","target":"update-cdn.paylo4d.example, 203.0.113.47","description":"Block at every layer this time, and verify the block from an affected host.","is_correct":true,"points":15,"feedback_md":"Correct, and note the lesson it encodes. This exact block was applied\nat one layer on 11 March and closed as done. Verify it from the host\nit is meant to protect.\n","requires_confirmation":false},{"key":"disable-praman","event_type":"ISOLATE_ACCOUNT","label":"Disable p.raman and reset her credentials","target":"NORTHWIND\\p.raman","description":"Disable the account whose session the malware ran in - and whose credentials were harvested in March and never reset.","is_correct":true,"points":10,"feedback_md":"Correct, and overdue by seven days. Her credentials were submitted to\na harvesting page on 11 March and never rotated.\n","requires_confirmation":false},{"key":"restore-immediately","event_type":"DOWNLOAD_ARTIFACT","label":"Begin restoring FS-SHARED-01 from backup now","target":"BKP-SRV-01 -> FS-SHARED-01","description":"Start the restore immediately to get departments working again.","is_correct":false,"points":20,"feedback_md":"You have restored clean data onto a network where the implant is\nstill resident and shares are still writable. It will be encrypted\nagain, and you will have consumed your recovery window and possibly\nyour restore point.\n\nRestoring before eradicating is the single most expensive mistake in\nransomware response. Recovery comes after eradication for a reason,\nand the pressure to skip that ordering will be enormous and will come\nfrom people senior to you.\n","requires_confirmation":true},{"key":"power-off-everything","event_type":"CONTAIN_HOST","label":"Power off all campus systems","target":"All campus endpoints and servers","description":"Hard shutdown of everything to guarantee the spread stops.","is_correct":false,"points":12,"feedback_md":"This stops the spread and destroys the volatile evidence you need to\nconfirm eradication, takes down systems that were never at risk, and\nmay corrupt files mid-write on machines that were fine.\n\nIt is not an unthinkable action - in some outbreaks it is the right\none. It is the wrong one when you have a targeted containment that\naddresses the actual mechanism, which you do.\n","requires_confirmation":true}],"hints":[{"key":"contain-hint-backup","text_md":"Ask what this incident looks like if the backup server is encrypted\ntoo. Then ask what you are doing to make sure that does not happen in\nthe next ten minutes.\n","cost":5},{"key":"contain-hint-shares","text_md":"Isolating hosts stops those hosts. What stopped the file server being\nencrypted was never about the file server''s own network connection.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["containment_scope"],"required_action_keys":["isolate-affected-hosts","isolate-backup-server","disable-share-access","block-c2-all-layers"],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'ransomware-outbreak'),
  'eradication'::phase_key, 3,
  'Eradication', 'This is the phase the 11 March incident skipped, which is why you are
here. Do it properly.

The question to keep asking: if this host rejoins the network tomorrow,
is there anything on it that could start this again?
', array['Remove the implant and its persistence wherever it exists.', 'Establish how many hosts carry the same persistence, not just the encrypted ones.', 'Rotate credentials compromised seven days ago and never reset.']::text[],
  '{"decisions":[{"key":"eradication_scope","prompt":"Which hosts need to be checked for the implant?","help_md":"The five encrypted hosts are the ones you know about. Think about what\nthe 11 March response did not do.\n","type":"select","options":[{"value":"entire_estate_hunt","label":"Every host in the estate, by hunting for the Run key and file hash","description":"The March incident was never swept, so the true footprint is unknown."},{"value":"five_affected_hosts","label":"The five hosts that were encrypted","description":"Clean the systems showing impact."},{"value":"hr_department_only","label":"The HR department, where it started","description":"Focus on the affected business unit."},{"value":"patient_zero_only","label":"WKS-HR-014 only","description":"Remove it from the origin."}],"expected":"entire_estate_hunt","points":20,"rationale_md":"The whole estate. This is the direct lesson of the previous incident:\nnobody swept then, so nobody knows how many machines received the\nsame phishing email, opened it, and are sitting quietly with a Run\nkey waiting for a payload.\n\nThe five encrypted hosts are the ones where the payload arrived. They\nare not necessarily the ones where the implant is.\n\nHunting for two indicators - the Run key path and the file hash -\nacross the estate is a few hours of work. Not doing it is how this\nrecurs in another seven days, and a second recurrence is no longer a\ntechnical failure but an institutional one.\n","require_rationale":true},{"key":"eradication_steps","prompt":"Which steps are required?","type":"multi_select","options":[{"value":"rebuild_all_affected","label":"Rebuild all five affected hosts from known-good images","description":"Do not clean encrypted, compromised systems in place."},{"value":"hunt_run_key_estate_wide","label":"Hunt for the Run key and implant hash across every host","description":"Find the machines carrying the persistence but not yet triggered."},{"value":"reset_praman_credentials","label":"Reset p.raman''s credentials and revoke her tokens","description":"Harvested on 11 March and never rotated."},{"value":"block_all_layers_verified","label":"Confirm the C2 block is effective at DNS, proxy and firewall from an affected host","description":"Verify, rather than assume, that the block applies."},{"value":"purge_original_phish","label":"Search the mail estate for the original 11 March phishing email and purge remaining copies","description":"Other mailboxes may still hold it."},{"value":"pay_ransom","label":"Pay the ransom to obtain the decryption key","description":"Recover the encrypted files directly."},{"value":"delete_encrypted_files","label":"Delete all encrypted files to free up space","description":"Clear the .nocturnelock files from affected systems."}],"expected":["rebuild_all_affected","hunt_run_key_estate_wide","reset_praman_credentials","block_all_layers_verified","purge_original_phish"],"points":20,"rationale_md":"Five steps, and note that two of them are finishing work that should\nhave happened on 11 March.\n\nPaying the ransom is not the SOC''s decision and is not eradication -\nit is a recovery option with legal, ethical and practical problems,\nand it does nothing about the implant. If the institution pays and\nrestores without eradicating, they are encrypted again with a\ndecryption key they have already bought once.\n\nDeleting the encrypted files is the quietly destructive option. Those\nfiles are evidence, they may be partially recoverable, and in some\nransomware families flawed implementations have been broken later.\nDeleting them forecloses that permanently to reclaim disk space.\n","require_rationale":false},{"key":"verification_of_eradication","prompt":"What would demonstrate that eradication succeeded?","type":"select","options":[{"value":"no_indicators_and_no_c2_for_period","label":"Estate-wide sweep returns no indicators, and no host resolves or connects to the C2 across a monitored period","description":"Absence confirmed by active searching plus time."},{"value":"antivirus_clean","label":"Antivirus reports clean on the rebuilt hosts","description":"Endpoint protection finds nothing."},{"value":"users_report_normal","label":"Users report their systems are working normally","description":"No further disruption reported."},{"value":"no_new_encryption","label":"No new encryption events for 24 hours","description":"The immediate impact has stopped."}],"expected":"no_indicators_and_no_c2_for_period","points":15,"rationale_md":"An active sweep that finds nothing, plus a monitored period with no\ncontact to the C2 infrastructure. Absence of evidence only counts as\nevidence of absence when you actually went looking.\n\nThe other three are what the 11 March response effectively relied on.\nAntivirus was clean then too - it never detected this implant. Users\nreported normal, because a beacon is invisible to the person using\nthe laptop. And there was no new encryption for seven days, right up\nuntil there was.\n","require_rationale":false}],"actions":[{"key":"request-forensic-images-ransom","event_type":"DOWNLOAD_ARTIFACT","label":"Capture forensic images of the affected hosts","target":"WKS-HR-014 and the four other affected systems","description":"Image disk and memory on all affected hosts before rebuilding.","is_correct":true,"points":10,"feedback_md":"Correct, and memory matters unusually much here: some ransomware\nfamilies leave key material in memory, and a host that is isolated\nbut still running is the only chance to capture it.\n","requires_confirmation":false}],"hints":[{"key":"erad-hint-sweep","text_md":"Read what the 11 March ticket says was *not* done. One of those\nomissions is the reason you cannot currently answer how many hosts\nare affected.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["eradication_scope","eradication_steps","verification_of_eradication"],"required_action_keys":["request-forensic-images-ransom"],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'ransomware-outbreak'),
  'recovery'::phase_key, 4,
  'Recovery', 'Read the backup status document before answering anything in this phase.

The institution has a usable backup, which puts it in a far better
position than most. But "a backup exists" and "we can restore from it"
are different claims, and the document tells you which one is actually
supported.

Sequence matters more here than anywhere else in this library.
', array['Judge whether the backup is genuinely usable.', 'Order recovery so restored data is not immediately re-encrypted.', 'Set realistic expectations about time to restore.']::text[],
  '{"decisions":[{"key":"backup_assessment","prompt":"Is the backup usable, and what is the risk?","help_md":"Check the recovery point, where the backup lives, and what has actually been tested.","type":"select","options":[{"value":"usable_but_never_fully_tested","label":"Usable - it survived and the recovery point is good - but a full system restore has never been tested","description":"The backup is intact; the restore process is unproven."},{"value":"fully_reliable","label":"Fully reliable - it is isolated, intact and regularly tested","description":"Recovery can proceed with confidence."},{"value":"unusable_encrypted","label":"Unusable - the ransomware reached it","description":"The backup was encrypted along with everything else."},{"value":"unusable_too_old","label":"Unusable - the recovery point is too old to be useful","description":"Too much would be lost."}],"expected":"usable_but_never_fully_tested","points":15,"rationale_md":"Usable, and unproven.\n\nWhat is good: it is on a separate VLAN with local credentials the\ndomain does not know, which is exactly why it survived. The 06:00\nincremental ran ninety minutes before encryption, so the recovery\npoint costs about ninety minutes of work.\n\nWhat is not: restore testing has only ever covered **single files**,\nmost recently in September 2024. Nobody has restored a whole system\nfrom this infrastructure, and the 14-20 hour estimate is a guess by\nsomeone who has never done it.\n\nThat distinction belongs in your report, because leadership will be\nasking \"when will we be back\" and the honest answer is \"we have a\ngood copy and an untested process.\" A restore that fails at hour\ntwelve is a very different Tuesday from one that succeeds.\n","require_rationale":true},{"key":"recovery_sequence","prompt":"In what order should recovery proceed?","type":"select","options":[{"value":"eradicate_then_rebuild_then_restore_then_reconnect","label":"Eradicate, rebuild hosts, restore data to clean systems, verify, then reconnect","description":"Nothing clean touches the network until the network is clean."},{"value":"restore_then_eradicate","label":"Restore the file server first to get departments working, then eradicate","description":"Prioritise getting the institution operating again."},{"value":"reconnect_then_monitor","label":"Reconnect the isolated hosts and watch for renewed activity","description":"Return to service and monitor closely."},{"value":"restore_in_parallel","label":"Restore and eradicate in parallel to save time","description":"Run both workstreams simultaneously under pressure."}],"expected":"eradicate_then_rebuild_then_restore_then_reconnect","points":20,"rationale_md":"Eradicate, rebuild, restore, verify, reconnect &mdash; in that order,\nand the order is the whole answer.\n\nRestoring first is the option leadership will push for, because it is\nthe one that gets people working. It restores clean data onto a\nnetwork where the implant is still present, and you lose the data and\nthe window.\n\nRestoring in parallel is the subtle version of the same mistake. It\nsounds efficient and it means clean data arrives before the\nenvironment is confirmed clean.\n\nBeing able to explain *why* the sequence cannot be compressed - to\nsomeone who is under real pressure and not being unreasonable - is\nthe most valuable thing an analyst can do in the hours after an\noutbreak.\n","require_rationale":true},{"key":"ransom_decision","prompt":"Who decides whether to pay, and what is your input?","type":"select","options":[{"value":"leadership_with_legal_soc_advises","label":"Leadership with legal advice; the SOC advises that a usable backup exists","description":"The SOC supplies facts; the decision sits above it."},{"value":"soc_decides_not_to_pay","label":"The SOC declines to pay on principle","description":"Refuse as a matter of policy."},{"value":"pay_to_restore_quickly","label":"Pay, because it is faster than restoring","description":"Buy the decryption key to reduce downtime."},{"value":"negotiate_for_time","label":"Open negotiations to extend the deadline","description":"Engage to buy time for recovery."}],"expected":"leadership_with_legal_soc_advises","points":10,"rationale_md":"Leadership, with legal advice. The SOC''s contribution is factual and\nit is decisive: **an intact backup exists with a ninety-minute\nrecovery point**. That single fact changes the conversation more than\nany argument about principle.\n\nPaying does not undo the breach, does not remove the implant, does\nnot guarantee a working decryptor, and may carry legal exposure\ndepending on who the operators are. Those are real considerations\nthat the SOC surfaces and does not decide.\n\nNegotiating and making contact are not neutral acts, and doing either\nwithout legal input forecloses options the institution may need.\n","require_rationale":false}],"actions":[],"hints":[{"key":"rec-hint-tested","text_md":"Look at the restore test history in the backup document. Check what\nscope was tested, not just whether tests happened.\n","cost":5},{"key":"rec-hint-order","text_md":"Ask what happens to restored files if the implant is still live on\nany host with write access to the share.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["backup_assessment","recovery_sequence","ransom_decision"],"required_action_keys":[],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'ransomware-outbreak'),
  'lessons_learned'::phase_key, 5,
  'Lessons Learned', 'This is the hardest review in the library to write honestly, because the
most important finding is about the SOC itself.

Seven days ago this team detected the intrusion correctly, blocked the C2
domain, and closed the ticket. Every individual decision was reasonable.
The host was not isolated because a colleague needed it during payroll
week. The block was applied where it was easiest to apply. Nobody swept
the estate because nothing suggested a second host.

Reviews that turn into blame produce teams that stop reporting things.
Reviews that avoid the finding entirely produce the same Tuesday again.
Write one that does neither: name what went wrong at the level of
*process*, and propose changes that would hold even when the next person
is under the same pressure.
', array['Identify the incomplete eradication as the proximate cause without blaming individuals.', 'Recommend process changes that survive time pressure.', 'Address backup assurance as well as prevention.']::text[],
  '{"decisions":[{"key":"primary_control_gap","prompt":"Which single failure most enabled this incident?","type":"select","options":[{"value":"incomplete_eradication_march","label":"The 11 March incident was closed without eradicating the persistence","description":"The implant remained resident for seven days."},{"value":"no_network_segmentation","label":"Insufficient network segmentation","description":"Shared drives allowed the encryption to reach the file server."},{"value":"mail_gateway_policy","label":"The mail gateway policy that let the original attachment through","description":"The initial access on 11 March."},{"value":"no_edr_blocking","label":"The endpoint agent detected but did not block","description":"Detection without prevention."}],"expected":"incomplete_eradication_march","points":15,"rationale_md":"The incomplete eradication. The mail gateway failure was real and it\nwas the previous incident''s finding, already recorded. What turned a\ncontained compromise into an estate-wide outbreak was closing the\nticket while the implant was still resident.\n\nBe precise in the write-up about what \"incomplete\" means here, because\nit is a checklist, not an attitude: the host was not isolated, not\nreimaged, the Run key stayed, credentials were not rotated, the block\nwas applied at one layer, and no sweep ran.\n\nSegmentation is a genuine finding and belongs in the report as a\ncontributing factor - it determined the blast radius once the payload\nran. It did not determine whether the payload ran.\n","require_rationale":true},{"key":"process_change","prompt":"Which process change would most reliably prevent a repeat?","type":"select","options":[{"value":"eradication_closure_criteria","label":"Incidents cannot be closed until documented eradication criteria are met, with exceptions signed off by name","description":"Make incomplete closure visible and accountable rather than silent."},{"value":"more_training","label":"Additional ransomware response training for the SOC","description":"Improve the team''s knowledge."},{"value":"buy_better_edr","label":"Procure an endpoint product with blocking enabled","description":"Replace detection with prevention."},{"value":"increase_soc_headcount","label":"Increase SOC staffing","description":"Add capacity so incidents get more attention."}],"expected":"eradication_closure_criteria","points":15,"rationale_md":"Closure criteria with named exceptions.\n\nThe team already knew the host should be rebuilt. They did not do it\nbecause somebody needed the laptop during payroll week, and no\nmechanism made that trade-off visible to anyone who could weigh it.\nThat is a process gap, not a knowledge gap, and training does not fix\nprocess gaps.\n\nThe key design detail is the **named exception**. The point is not to\nmake rebuilding mandatory regardless of circumstance - sometimes the\nlaptop genuinely is needed. It is to make skipping it a decision\nsomebody owns in writing, rather than something that quietly does not\nhappen.\n\nMore headcount and better tooling both help and neither addresses the\nspecific failure, which is that an incident was allowed to close in a\nstate everyone would have recognised as incomplete if anyone had been\nasked.\n","require_rationale":true}],"actions":[],"hints":[{"key":"ll-hint-blame","text_md":"Test each recommendation by asking: would this have held on 11 March,\nwith the same people, the same pressure and the same deadline? If it\nrelies on somebody being more careful, it would not have.\n","cost":3}]}'::jsonb, '{"required_decision_keys":["primary_control_gap","process_change"],"required_action_keys":[],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":true,"reflection_min_words":160}'::jsonb
);

delete from scenario_assets where scenario_id = (select id from scenarios where slug = 'ransomware-outbreak');

insert into scenario_assets (scenario_id, external_id, asset_type, content, is_decoy, reveal_phase) values
((select id from scenarios where slug = 'ransomware-outbreak'), 'alert-av-scan', 'ticket'::asset_type, '{"kind":"alert","id":"alert-av-scan","title":"Scheduled antivirus scan completed","severity":"info","source":"Northwind EDR","first_seen":"2025-03-18T07:15:00.000Z","description":"Routine scheduled scan on WKS-FIN-003 completed with no detections. Expected daily activity.","host":"WKS-FIN-003","is_decoy":true,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":[],"linked_log_ids":["log-edr-n001"]}'::jsonb, true, 'triage'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'alert-c2-return', 'ticket'::asset_type, '{"kind":"alert","id":"alert-c2-return","title":"Resolution of a previously blocked command-and-control domain","severity":"critical","source":"Network Detection","first_seen":"2025-03-18T07:38:09.000Z","description":"WKS-HR-014 resolved update-cdn.paylo4d.example and downloaded 1.8 MB from it at 07:39 - three minutes before encryption started. This domain was blocked at the proxy after incident INC-2025-0311 on 11 March, but never at DNS or the firewall.","host":"WKS-HR-014","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":200,"linked_document_ids":["doc-prior-incident"],"linked_log_ids":["log-dns-c2-return","log-proxy-payload-pull","log-edr-runkey-persist"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'alert-shadow-delete', 'ticket'::asset_type, '{"kind":"alert","id":"alert-shadow-delete","title":"Volume shadow copies deleted","severity":"critical","source":"Northwind EDR","first_seen":"2025-03-18T07:40:58.000Z","description":"vssadmin delete shadows /all /quiet executed on WKS-HR-014, fourteen seconds before encryption began. Local recovery points are gone.","host":"WKS-HR-014","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":[],"linked_log_ids":["log-edr-vssadmin","log-edr-service-stop"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'alert-mass-encryption', 'ticket'::asset_type, '{"kind":"alert","id":"alert-mass-encryption","title":"Mass file rename in progress on WKS-HR-014","severity":"critical","source":"Northwind EDR","first_seen":"2025-03-18T07:41:12.000Z","description":"1,842 files renamed to a .nocturnelock extension in sixty seconds. The process doing it is onedrivesync.exe, running from AppData.","host":"WKS-HR-014","user":"p.raman","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":["doc-ransom-note"],"linked_log_ids":["log-edr-mass-rename","log-edr-vssadmin"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'alert-spread', 'ticket'::asset_type, '{"kind":"alert","id":"alert-spread","title":"Mass file rename detections on four more hosts","severity":"critical","source":"Northwind EDR","first_seen":"2025-03-18T07:49:33.000Z","description":"The same detection has now fired on WKS-HR-015, WKS-FIN-003, WKS-ADM-021 and the shared file server FS-SHARED-01. 47,000 files affected across the estate.","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":60,"linked_document_ids":["doc-impact-summary"],"linked_log_ids":["log-ticket-summary","log-fs-mapped-drive"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'log-fs-n001', 'auth_log'::asset_type, '{"kind":"log","id":"log-fs-n001","ts":"2025-03-18T02:00:14.000Z","source":"backup","message":"BACKUP_JOB host=BKP-SRV-01 target=FS-SHARED-01 status=success files=402118 size=1284807168 type=full","host":"BKP-SRV-01","action":"backup","severity":"info","fields":{"status":"success","files":402118,"type":"full","note":"The nightly backup completed at 02:00, five and a half hours before encryption began."},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'log-edr-n002', 'edr_alert'::asset_type, '{"kind":"log","id":"log-edr-n002","ts":"2025-03-18T06:50:33.000Z","source":"edr","message":"PROCESS host=WKS-ADM-021 user=NORTHWIND\\s.menon parent=explorer.exe image=OUTLOOK.EXE args=\"\"","host":"WKS-ADM-021","user":"s.menon","action":"process_create","severity":"info","fields":{"note":"Somebody opening Outlook. Unremarkable, and it is what makes the March 11 detection remarkable."},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'log-auth-n001', 'auth_log'::asset_type, '{"kind":"log","id":"log-auth-n001","ts":"2025-03-18T07:12:40.000Z","source":"auth","message":"EventID=4624 Logon Type=2 (Interactive) Account=NORTHWIND\\j.tan Workstation=WKS-LIB-008 Status=Success","host":"WKS-LIB-008","user":"j.tan","action":"logon_success","fields":{"event_id":4624},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
((select id from scenarios where slug = 'ransomware-outbreak'), 'log-edr-n001', 'edr_alert'::asset_type, '{"kind":"log","id":"log-edr-n001","ts":"2025-03-18T07:15:00.000Z","source":"edr","message":"PROCESS host=WKS-FIN-003 user=NORTHWIND\\k.lim parent=services.exe image=MsMpEng.exe args=\"scheduled scan\"","host":"WKS-FIN-003","action":"process_create","severity":"info","fields":{"note":"Scheduled antivirus scan."},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
