((select id from scenarios where slug = 'ransomware-outbreak'), 'log-fs-mapped-drive', 'file_share_log'::asset_type, '{"kind":"log","id":"log-fs-mapped-drive","ts":"2025-03-18T07:49:30.000Z","source":"fileshare","message":"ACCESS host=FS-SHARED-01 user=NORTHWIND\\p.raman share=\\\\FS-SHARED-01\\Departments operation=write files=41882 source_host=WKS-HR-014","host":"FS-SHARED-01","user":"p.raman","action":"write","severity":"critical","fields":{"share":"Departments","file_count":41882,"source_host":"WKS-HR-014","note":"The file server was encrypted over a mapped drive from the first workstation. The malware did not need to move host at all - it just followed the drive letter."},"is_decoy":false,"reveal_phase":"investigation"}'::jsonb, false, 'investigation'::phase_key),
