((select id from scenarios where slug = 'webapp-sql-injection'), 'log-app-error', 'http_access_log'::asset_type, '{"kind":"log","id":"log-app-error","ts":"2025-06-17T14:24:19.000Z","source":"http","message":"APPLICATION ERROR /api/search - psycopg2.errors.SyntaxError: unterminated quoted string at or near \"''\" LINE 1: SELECT id, title, body FROM articles WHERE title LIKE ''%''%''","host":"WEB-PORTAL-01","src_ip":"203.0.113.188","action":"error","severity":"high","fields":{"exception":"psycopg2.errors.SyntaxError","leaked_query":"SELECT id, title, body FROM articles WHERE title LIKE ''%<input>%''","framework":"Flask 2.0.1 / psycopg2 2.9.3","note":"The error page returned the failing SQL statement to the attacker. This is how they learned the query shape in one request instead of fifty."},"is_decoy":false,"reveal_phase":"investigation"}'::jsonb, false, 'investigation'::phase_key),
