((select id from scenarios where slug = 'webapp-sql-injection'), 'log-http-sqli-003', 'http_access_log'::asset_type, '{"kind":"log","id":"log-http-sqli-003","ts":"2025-06-17T14:27:21.000Z","source":"http","message":"GET /api/search?q='' UNION SELECT NULL-- HTTP/1.1 500 1204 \"-\" \"python-requests/2.31.0\"","host":"WEB-PORTAL-01","src_ip":"203.0.113.188","action":"error","severity":"high","fields":{"status":500,"bytes":1204,"path":"/api/search","param_q":"'' UNION SELECT NULL--","note":"Column-count probing. The error tells them the number was wrong."},"is_decoy":false,"reveal_phase":"investigation"}'::jsonb, false, 'investigation'::phase_key),
