((select id from scenarios where slug = 'webapp-sql-injection'), 'log-http-login-bypass', 'http_access_log'::asset_type, '{"kind":"log","id":"log-http-login-bypass","ts":"2025-06-17T14:41:08.000Z","source":"http","message":"POST /api/login HTTP/1.1 302 512 \"-\" \"python-requests/2.31.0\" user=admin'' -- ","host":"WEB-PORTAL-01","src_ip":"203.0.113.188","action":"allowed","severity":"critical","fields":{"status":302,"path":"/api/login","param_username":"admin'' -- ","note":"Authentication bypass: the comment removes the password check from the query entirely."},"is_decoy":false,"reveal_phase":"investigation"}'::jsonb, false, 'investigation'::phase_key),
